// th16_s2_b3: TH16 v1.00a Stage 2 boss, second nonspell.
// Source: st02bs.ecl.txt Boss2:126-185 (entered from BossCard1:304).
// Source window: timerReset/setInterrupt(0,2200,1500,"BossCard2") -> 1500 frames.
// Card window: 120-frame shell buffer + full 1500-frame source segment + startup margin.

const TIME_LIMIT: int = 1624;
const OPENING_BUFFER: int = 120;

// Approved TH16 aliases of the shared 0-43 bullet slots.
const TH16_KUNAI: int = 496;

// moveLimit(0, 96, 280, 48): position box x in [-140,140], y in [72,120];
// direction-choice inner box x +/-70, y 84..108 (width/height quarter rule).
// Enemy int slot 0 = next movement step, fx slots 0/1 = logical unit direction.
sub card_arm_next_step() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 40 { speed = 2fx * (40 - k) / 40; }
    var nx: fx = $self_x + self_fx(0) * speed;
    var ny: fx = $self_y + self_fx(1) * speed;
    if nx < -140fx { nx = -140fx; }
    if nx > 140fx { nx = 140fx; }
    if ny < 72fx { ny = 72fx; }
    if ny > 120fx { ny = 120fx; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

sub card_begin_angle(a: int) {
    set_self_fx(0, cos(a as angle));
    set_self_fx(1, sin(a as angle));
    set_self_int(0, 0);
    card_arm_next_step();
}

sub card_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        card_arm_next_step();
    }
}

// moveRand(40, 4, 2.0): fixed direction drawn once, speed 2.0 -> 0 linearly
// over 40 steps; mode parameter does not touch the speed slot (mode 0 inherited).
sub card_move_rand() {
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < -70fx {
        a = r / 3;
    } else if $self_x > 70fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < 84fx {
        if a < 0 { a = -a; }
    } else if $self_y > 108fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    card_begin_angle(a);
}

// Boss2_at: etNew/etSprite(9,color)/etAim(0)/etCount(7,1)/etSpeed once, then per
// volley etOffsetRad(C,E), etAngle(RANDF2*4deg, 30deg + RANDF2*2deg), etOn, wait.
// Speed stack: Easy 1.8, N/H/L 2.4 (single layer uses s0 only).
// 30deg = 5461 BAM, 4deg = 728 BAM, 2deg = 364 BAM.
sub boss2_at(color: int, cstep: int, speed: fx, count: int, step_wait: int) {
    var c: int = 0;
    var e: fx = 20fx;
    sh_reset(0);
    sh_sprite(0, TH16_KUNAI, color);
    sh_ring(0, 0);
    sh_aim(0, 1);
    sh_count(0, 7, 1);
    sh_speed(0, speed, 0fx);
    for i in 0..count {
        var ua: fx = (rand(65536) - 32768) as fx / 32768;
        var ub: fx = (rand(65536) - 32768) as fx / 32768;
        var alpha: int = (ua * 728fx) as int;
        var delta: int = 5461 + ((ub * 364fx) as int);
        sh_offset_rad(0, c as angle, e);
        sh_angle(0, alpha as angle, delta as angle);
        sh_fire(0);
        c = c + cstep;
        if e <= 80fx { e = e + 2fx; }
        wait(step_wait);
    }
}

async sub boss2_async(color: int, cstep: int, speed: fx, count: int, step_wait: int) {
    boss2_at(color, cstep, speed, count, step_wait);
}

async sub boss_main() {
    set_invuln(65535);
    set_hitbox(24fx);   // source setHitbox(48,48) -> radius 24
    set_hurtbox(20fx);  // source setHurtbox(40,40) -> radius 20
    // Source entry resets: moveVel(0,0) + moveVelTime(0,0,0,0) stop all layering;
    // movePosTime(0,0,...) only cancels the position interpolation (no teleport).
    move_vel(0, 0deg, 0fx, EASE_LINEAR);
    // Source etCancel(640) twice (TIMEOUT==0 entry path).
    clear_bullets_at($self_x, $self_y, 640fx, 0);
    clear_bullets_at($self_x, $self_y, 640fx, 0);
    // Source movePosTime(90, 9, 0, 96): entry position is normalized to (0,96).
    move_to(90, 0fx, 96fx, EASE_QUAD_IN_OUT);
    wait(60);
    wait(60);

    var cnt: int = 40;
    var spd: fx = 2.4fx;
    var sw: int = 10;
    var rk: int = global(GVAR_RANK);
    if rk == RANK_EASY {
        cnt = 20; spd = 1.8fx; sw = 20;
    } else if rk == RANK_NORMAL {
        cnt = 40; spd = 2.4fx; sw = 10;
    } else if rk == RANK_HARD {
        cnt = 100; spd = 2.4fx; sw = 5;
    } else {
        cnt = 120; spd = 2.4fx; sw = 3;
    }

    loop {
        // Boss2_1176: async Boss2_at(0, color 4, +30deg); wait(5); sync
        // Boss2_at(1, color 6, -20deg); wait(10); moveRand(40,4,2.0); wait(50).
        spawn boss2_async(4, 5461, spd, cnt, sw);
        wait(5);
        boss2_at(6, -3641, spd, cnt, sw);
        wait(10);
        card_move_rand();
        card_wait(40);
        wait(10);
    }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 96fx, 13200, 1, 0, 0, boss_main);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    kill_all_enemies(KILL_SILENT);
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
